(function(){
  // 小型 loader：先加载 JSZip，再加载 epub.js（多个 CDN 回退）
  var JSZIP_URLS = [
    'https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js'
  ];

  var EPUB_URLS = [
    'https://cdn.jsdelivr.net/npm/epubjs@0.3.88/dist/epub.min.js',
    'https://unpkg.com/epubjs@0.3.88/dist/epub.min.js'
  ];

  function loadScript(url, onload, onerror) {
    var s = document.createElement('script');
    s.src = url;
    s.crossOrigin = 'anonymous';
    s.onload = onload;
    s.onerror = onerror;
    document.head.appendChild(s);
  }

  function tryLoadList(urls, idx, onSuccess, onAllFailed) {
    if (idx >= urls.length) {
      if (onAllFailed) onAllFailed();
      return;
    }
    loadScript(urls[idx], function(){
      console.log('Loaded script:', urls[idx]);
      if (onSuccess) onSuccess(urls[idx]);
    }, function(){
      console.warn('Failed to load script:', urls[idx]);
      tryLoadList(urls, idx+1, onSuccess, onAllFailed);
    });
  }

  // 1) 先加载 JSZip（如果还没加载）
  if (typeof JSZip === 'undefined') {
    console.log('epub loader: JSZip not found, loading JSZip...');
    tryLoadList(JSZIP_URLS, 0, function(){
      console.log('epub loader: JSZip loaded');
      // 2) 再加载 epub.js
      loadEpubJS();
    }, function(){
      console.error('epub loader: failed to load JSZip from all CDNs. EPUB parsing will fail.');
    });
  } else {
    loadEpubJS();
  }

  function loadEpubJS(){
    if (typeof ePub !== 'undefined') {
      console.log('epub loader: ePub already defined');
      return;
    }
    console.log('epub loader: loading epub.js from CDN fallbacks...');
    tryLoadList(EPUB_URLS, 0, function(url){
      console.log('epub loader: epub.js loaded from ' + url);
    }, function(){
      console.error('epub loader: failed to load epub.js from all CDNs.');
    });
  }
})();
